import React, { useState } from "react";
import Navbar from "../components/Navbar";
import Footer from "../components/Footer";
import categories from "../data/categories";
import "./PageShell.css";

const initialForm = { name: "", email: "", phone: "", vertical: "General", message: "" };

export default function SendQuery() {
  const [form, setForm] = useState(initialForm);
  const [status, setStatus] = useState(null); // { ok: boolean, message: string }
  const [submitting, setSubmitting] = useState(false);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSubmitting(true);
    setStatus(null);
    try {
      const res = await fetch("/api/queries", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Something went wrong.");
      setStatus({ ok: true, message: "Thanks — your query has been sent." });
      setForm(initialForm);
    } catch (err) {
      setStatus({ ok: false, message: err.message });
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div>
      <Navbar />
      <div className="page">
        <h1>Send Query</h1>
        <p>Tell us what you need and which vertical it relates to — we'll get back to you.</p>

        <form className="form" onSubmit={handleSubmit}>
          <label>
            Name
            <input name="name" value={form.name} onChange={handleChange} required />
          </label>
          <label>
            Email
            <input type="email" name="email" value={form.email} onChange={handleChange} required />
          </label>
          <label>
            Phone (optional)
            <input name="phone" value={form.phone} onChange={handleChange} />
          </label>
          <label>
            Vertical
            <select name="vertical" value={form.vertical} onChange={handleChange}>
              <option value="General">General</option>
              {categories.map((c) => (
                <option key={c.key} value={c.label}>
                  {c.label}
                </option>
              ))}
            </select>
          </label>
          <label>
            Message
            <textarea name="message" value={form.message} onChange={handleChange} required />
          </label>

          {status && (
            <div className={`form__status ${status.ok ? "form__status--ok" : "form__status--err"}`}>
              {status.message}
            </div>
          )}

          <button type="submit" disabled={submitting}>
            {submitting ? "Sending..." : "Send Query"}
          </button>
        </form>
      </div>
      <Footer />
    </div>
  );
}
